import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ServerSettingsRequest{}
EMPTY = bytes.fromhex("")

GOLDENS = [
    pytest.param(v.ServerSettingsRequestPacket(), EMPTY, id=f"{v.__name__.rpartition('.')[2]}-empty") for v in VERSIONS
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_server_settings_request_is_packet_102(version):
    assert version.PACKETS[102] is version.ServerSettingsRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_settings_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_settings_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_server_settings_request_rejects_trailing_bytes(version):
    with pytest.raises(ValueError, match="trailing bytes"):
        version.ServerSettingsRequestPacket.from_bytes(b"\x7f")
